#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int *assessments;
    int num_assess;
} Course;

typedef struct {
    Course *courses;
    int num_courses;
} Student;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Student *students = (Student *)malloc(n * sizeof(Student));
    if (!students) return 0;

    for (int i = 0; i < n; i++) {
        int c;
        scanf("%d", &c);
        students[i].num_courses = c;
        students[i].courses = (Course *)malloc(c * sizeof(Course));

        for (int j = 0; j < c; j++) {
            int a;
            scanf("%d", &a);
            students[i].courses[j].num_assess = a;
            students[i].courses[j].assessments = (int *)malloc(a * sizeof(int));

            for (int k = 0; k < a; k++) {
                scanf("%d", &students[i].courses[j].assessments[k]);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        printf("Student %d:\n", i + 1);
        double student_total = 0.0;
        int total_assessments = 0;

        for (int j = 0; j < students[i].num_courses; j++) {
            int sum = 0;
            for (int k = 0; k < students[i].courses[j].num_assess; k++) {
                sum += students[i].courses[j].assessments[k];
            }
            double avg = (double)sum / students[i].courses[j].num_assess;
            printf("Course %d Average: %.2f\n", j + 1, avg);
            student_total += sum;
            total_assessments += students[i].courses[j].num_assess;
        }

        double overall = student_total / total_assessments;
        printf("Overall Average: %.2f\n", overall);
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < students[i].num_courses; j++) {
            free(students[i].courses[j].assessments);
        }
        free(students[i].courses);
    }
    free(students);

    return 0;
}
